using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OrionUnitDetailJoystickInput", menuName = "Data/Characters/OrionUnitDetailJoystickInput")]
public class OrionUnitDetailJoystickInput : UnitDetailJoystickInput
{
	private ZoomableInstance[] zoomableInstances = new ZoomableInstance[0];

	private int currentIndex;

	private ZoomableInstance currentZoomableInstance => zoomableInstances[currentIndex];

	public void InitializeZoomableInstance(StarAbilityInstance[] starAbilityInstances)
	{
		zoomableInstances = new ZoomableInstance[4];
		for (int i = 0; i < starAbilityInstances.Length; i++)
		{
			zoomableInstances[i] = starAbilityInstances[i];
		}
	}

	public override void AxisLeftInput()
	{
		currentZoomableInstance.OnMouseExit();
		if (currentIndex < zoomableInstances.Length - 1)
		{
			currentIndex++;
		}
		else
		{
			currentIndex = 0;
		}
		currentZoomableInstance.OnMouseOver();
	}

	public override void AxisRightInput()
	{
		currentZoomableInstance.OnMouseExit();
		if (currentIndex > 0)
		{
			currentIndex--;
		}
		else
		{
			currentIndex = zoomableInstances.Length - 1;
		}
		currentZoomableInstance.OnMouseOver();
	}

	public override void AxisUpInput()
	{
		OnMouseExitOnMouseOver();
	}

	public override void AxisDownInput()
	{
		OnMouseExitOnMouseOver();
	}

	public override void GoToCharacterDetail()
	{
		currentIndex = 0;
		currentZoomableInstance.OnMouseOver();
	}

	public override void DisableCharacterDetail()
	{
		currentZoomableInstance.OnMouseExit();
	}

	private void OnMouseExitOnMouseOver()
	{
		currentZoomableInstance.OnMouseExit();
		currentZoomableInstance.OnMouseOver();
	}
}
